import { query } from '../db.js';

export class OrderRepository {
  findByUser(userId) {
    return new Promise((resolve, reject) => {
      query('orders', (o) => o.user_id === userId && o.deleted_at === null,
        (err, rows) => (err ? reject(err) : resolve(rows)));
    });
  }

  findPaid() {
    return new Promise((resolve, reject) => {
      query('orders', (o) => o.status === 'paid' && o.deleted_at === null,
        (err, rows) => (err ? reject(err) : resolve(rows)));
    });
  }
}
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { UserRepository } from '../src/repositories/user-repository.js';
import { OrderRepository } from '../src/repositories/order-repository.js';

test('UserRepository.findActive matches the service behaviour', async () => {
  const users = await new UserRepository().findActive();
  assert.equal(users.length, 2);
});

test('UserRepository.findByEmail returns active matches and ignores deleted users', async () => {
  const repository = new UserRepository();
  assert.equal((await repository.findByEmail('ada@example.com')).id, 1);
  assert.equal(await repository.findByEmail('alan@example.com'), null);
  assert.equal(await repository.findByEmail('missing@example.com'), null);
});

test('OrderRepository.findPaid matches the service behaviour', async () => {
  const orders = await new OrderRepository().findPaid();
  assert.equal(orders.length, 3);
});
